function isAdminLocation(){return location.hash===ADMIN_HASH}
function adminMeta(){return st.snapshot?.metadata||st.snapshot?.meta||{}}
function adminModelVersion(){const m=adminMeta();return m.version||m.model_version||st.snapshot?.version||st.snapshot?.model_version||'Production snapshot'}
function adminPrimitiveRows(obj,limit=18){if(!obj||typeof obj!=='object')return'';return Object.entries(obj).filter(([,v])=>v==null||['string','number','boolean'].includes(typeof v)).slice(0,limit).map(([k,v])=>`<div class="admin-kv"><span>${esc(k)}</span><strong>${esc(v==null?'—':v)}</strong></div>`).join('')}
async function loadAdminManifest(force=true){st.adminManifest=(force?await liveJson('/data/snapshot_version.json',{}):await json('/data/snapshot_version.json',{}))||{};return st.adminManifest}
async function adminLoad(force=false){await Promise.all([players(force),loadSeasonStats(force),loadAdminManifest(true)]);st.adminLoadedAt=Date.now()}
