function adminCard(label,value,sub=''){return`<div class="admin-metric"><span>${esc(label)}</span><strong>${esc(value??'—')}</strong>${sub?`<small>${esc(sub)}</small>`:''}</div>`}
function adminOverview(){const cov=adminCoverage(),manifest=st.adminManifest||{},loaded=st.adminLoadedAt?new Date(st.adminLoadedAt).toLocaleTimeString():'—';return`<div class="admin-grid admin-grid-4">${adminCard('Web version',WEB_VERSION,'Hidden console')}${adminCard('Model version',adminModelVersion())}${adminCard('Projection week',st.snapshot?.projection_week??st.week)}${adminCard('NFL week',st.nflWeek??'—')}${adminCard('Model players',fi(st.rows.length))}${adminCard('Week coverage',cov.total?`${cov.projected}/${cov.total}`:'—','QB/RB/WR/TE')}${adminCard('Sleeper directory',st.players?fi(Object.keys(st.players).length):'—')}${adminCard('Season-stat rows',fi(st.seasonStats.size),'Current regular season')}</div><div class="admin-split"><section class="admin-panel"><div class="admin-panel-title">Snapshot manifest</div>${adminPrimitiveRows(manifest)||'<p class="muted">No manifest fields are currently exposed.</p>'}</section><section class="admin-panel"><div class="admin-panel-title">Runtime</div>${adminPrimitiveRows(adminMeta())||'<p class="muted">No primitive metadata fields are currently exposed.</p>'}<div class="admin-kv"><span>Admin data loaded</span><strong>${esc(loaded)}</strong></div></section></div><div class="admin-warning"><strong>Hidden route, not authentication.</strong><span>This console is intentionally absent from navigation and normal routing, but anyone who inspects the shipped JavaScript could discover it. Sensitive write operations are therefore not exposed here.</span></div>`}
